// === Tab: mySketch ===
// --- Configuration ---
const MAX_RIPPLES = 100; 

let gridShader; 
let ripples = []; 

// --- Shaders ---
const vertShader = `
  precision highp float;
  attribute vec3 aPosition;
  attribute vec2 aTexCoord;
  varying vec2 vTexCoord;
  void main() {
    vTexCoord = aTexCoord;
    vec4 positionVec4 = vec4(aPosition, 1.0);
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
    gl_Position = positionVec4;
  }
`;

const fragShader = `
  precision highp float;
  uniform float u_time;
  uniform vec2 u_resolution;
  uniform vec4 u_ripplesA[${MAX_RIPPLES}]; 
  uniform vec4 u_ripplesB[${MAX_RIPPLES}]; 
  varying vec2 vTexCoord;

  void main() {
    float x = vTexCoord.x;
    float y = vTexCoord.y;
    float aspect = u_resolution.x / u_resolution.y;

    float horizon = 0.8;
    if (y > horizon) {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0); 
        return;
    }

    float distFromHorizon = horizon - y;
    float depth = 1.0 / max(distFromHorizon, 0.001); 

    vec2 w_uv;
    w_uv.x = (x - 0.5) * aspect * depth; 
    w_uv.y = depth;

    vec2 totalDisplacement = vec2(0.0);

    for (int i = 0; i < ${MAX_RIPPLES}; i++) {
      vec2 center = u_ripplesA[i].xy;
      float startTime = u_ripplesA[i].z;
      float speed = u_ripplesA[i].w;

      if (startTime <= 0.0) continue;

      float numWaves = u_ripplesB[i].x;
      float frequency = u_ripplesB[i].y;
      float amplitude = u_ripplesB[i].z;

      float age = u_time - startTime;

      // --- 減衰の変更ポイント ---
      // 寿命を約250フレームに設定し、それを超えると完全に消えるように
      float lifespan = 250.0;
      if (age > lifespan) continue;

      // 1. 指数関数的な減衰（急激に小さくなり、後半は緩やかに）
      float decay = exp(-age * 0.015); 

      // 2. 寿命の終わりに向けた滑らかなフェードアウト
      float fadeOut = smoothstep(lifespan, lifespan * 0.5, age);

      // 波の広がり（半径）
      float currentRadius = age * speed;

      vec2 dir = w_uv - center;
      float dist = length(vec2(dir.x, dir.y * 2.0)); 

      float waveRegionWidth = (6.28318 / frequency) * numWaves;
      float distToWavefront = currentRadius - dist;

      // 波が存在する範囲の窓関数
      float envelope = smoothstep(waveRegionWidth, waveRegionWidth * 0.5, abs(distToWavefront - waveRegionWidth * 0.5));

      if (envelope > 0.0) {
        float wave = sin((dist - currentRadius) * frequency);
        // 強度 = 元の振幅 * 指数減衰 * フェードアウト * 窓関数
        float strength = amplitude * decay * fadeOut * envelope * 4.0;
        totalDisplacement += normalize(dir + 0.0001) * wave * strength;
      }
    }

    vec2 final_w_uv = w_uv + totalDisplacement;
    float stripeDensity = 2.5; 
    float flowSpeed = u_time * -0.005; 

    float stripePattern = 0.5 + 0.5 * cos((final_w_uv.y - flowSpeed) * stripeDensity);

    vec3 colorA = vec3(0.0, 0.0, 0.0); 
    vec3 colorB = vec3(0.3, 0.7, 1.0); 
    vec3 stripeGradient = mix(colorA, colorB, stripePattern);

    float fog = smoothstep(0.0, 0.7, distFromHorizon * 1.5);
    vec3 bgColor = vec3(0.0, 0.01, 0.03); 

    gl_FragColor = vec4(mix(bgColor, stripeGradient, fog), 1.0);
  }
`;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
	  // スクロールバーが出ないようにスタイルを直接書き換える
  let canvas = document.querySelector('canvas');
  canvas.style.display = 'block';
  document.body.style.overflow = 'hidden';
  document.body.style.margin = '0';
  document.body.style.padding = '0';
  gridShader = createShader(vertShader, fragShader);

  for (let i = 0; i < MAX_RIPPLES; i++) {
    ripples.push(createNewRipple(true));
  }
}

function draw() {
  background(0);
  shader(gridShader);

  let rainIntensity = noise(frameCount * 0.005); 
  let dropChance = map(rainIntensity, 0, 1, 0.05, 0.4);

  if (random() < dropChance) {
    dropWater();
  }

  let dataA = [];
  let dataB = [];
  for (let r of ripples) {
    dataA.push(r.x, r.y, r.startTime, r.speed);
    dataB.push(r.numWaves, r.frequency, r.amplitude, 0.0);
  }

  gridShader.setUniform('u_time', float(frameCount));
  gridShader.setUniform('u_resolution', [width, height]);
  gridShader.setUniform('u_ripplesA', dataA);
  gridShader.setUniform('u_ripplesB', dataB);

  rect(-width / 2, -height / 2, width, height); 
}

function createNewRipple(isInitial = false) {
  let aspect = width / height;
  let depth = random(1.7, 45.0);
  let horizontalLimit = 0.5 * aspect * depth;

  return {
    x: random(-horizontalLimit, horizontalLimit), 
    y: depth,
    // 初期状態では画面外（ずっと過去）に設定して、徐々に現れるように
    startTime: isInitial ? -1000 : frameCount,
    speed: random(0.004, 0.008),
    numWaves: random(1.0, 2.0),
    frequency: random(60.0, 100.0),
    amplitude: random(0.6, 1.5) 
  };
}

function dropWater() {
  let oldestIdx = 0;
  let minTime = Infinity;
  // 最も古い波（すでに消えている可能性が高いもの）を探して上書き
  for (let i = 0; i < ripples.length; i++) {
    if (ripples[i].startTime < minTime) {
      minTime = ripples[i].startTime;
      oldestIdx = i;
    }
  }
  ripples[oldestIdx] = createNewRipple();
}

function mousePressed() {
  let aspect = width / height;
  let uvy = 1.0 - ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height);
  let horizon = 0.8;

  if (uvy < horizon) {
    let depth = 1.0 / max(horizon - uvy, 0.001);
    let oldestIdx = 0;
    let minTime = Infinity;
    for (let i = 0; i < ripples.length; i++) {
      if (ripples[i].startTime < minTime) {
        minTime = ripples[i].startTime;
        oldestIdx = i;
      }
    }

    let r = createNewRipple();
    r.x = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width - 0.5) * aspect * depth; 
    r.y = depth;
    r.startTime = frameCount;
    r.amplitude = 2.0; // クリック時は少し強めに
    ripples[oldestIdx] = r;
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
